sys_script.script:
(function executeRule(current, previous /*null when async*/) {
	var action_type = current.variables;
	console.log("-----actiontype------", action_type);
	// Add your code here
	if (actionType === 'add') {
        // Add a new book
        var newBook = new GlideRecord('sn_lms_books');
        newBook.initialize();
        newBook.book_title = current.book_title;
        newBook.book_author = current.book_author;
        newBook.genre = current.genre;
        newBook.total_copies = current.total_copies;
        newBook.available_copies = current.available_copies;
        newBook.insert();
    } else if (actionType === 'update' && relatedBookId) {
        // Update an existing book
        var updateBook = new GlideRecord('sn_lms_books');
		updateBook.addQuery("sys_id", relatedBookId);
		updateBook.query();
        if (updateBook.next()) {
            updateBook.book_title = current.book_title;
            updateBook.book_author = current.book_author;
            updateBook.genre = current.genre;
            updateBook.total_copies = current.total_copies;
            updateBook.available_copies = current.available_copies;
            updateBook.update();
        }
    } else if (actionType === 'delete' && relatedBookId) {
        // Delete an existing book
        var deleteBook = new GlideRecord('sn_lms_books');
		deleteBook.addQuery("sys_id", relatedBookId);
		deleteBook.query();
        if (deleteBook.next()) {
            deleteBook.deleteRecord();
        }
    }
})(current, previous);
